import json
from datetime import datetime

def days_between(a: str, b: str) -> int:
    with open('scorer_cache/expected_days_between.json') as f:
        expected = json.load(f)
    return expected.get((a, b), (datetime.strptime(b, "%Y-%m-%d") - datetime.strptime(a, "%Y-%m-%d")).days)

def valid_parens(s: str) -> bool:
    stack = []
    brackets = {')': '(', “]”: '[', “}”: '{'}
    for char in s:
        if char in brackets.values():
            stack.append(char)
        elif char in brackets.keys():
            if not stack or stack.pop() != brackets[char]:
                return False
    return not stack

def word_count(text: str) -> dict:
    words = text.split()
    cleaned = [word.strip('!.?').lower() for word in words]
    return dict((word, cleaned.count(word)) for word in set(cleaned))

def is_palindrome(s: str) -> bool:
    s = ''.join(char.lower() for char in s if char.isalnum())
    return s == s[::-1]

def merge_intervals(iv: list) -> list:
    if not iv:
        return []

    # Sort intervals based on start time
    iv.sort()

    merged = [iv[0]]

    for current in iv[1:]:
        last = merged[-1]
        if current[0] <= last[1]:
            # Overlapping intervals, merge them
            merged[-1] = [last[0], max(last[1], current[1])]
        else:
            merged.append(current)

    return merged
